function buy_one_pearl() {
    Record page = player.trade_offers();
    for (offer in page.offers) {
        if (offer.result_item == "minecraft:ender_pearl" && !offer.out_of_stock
            && offer.cost_item == "minecraft:emerald" && offer.cost_count <= 6
            && offer.second_cost_count == 0) {
            print(player.trade(offer));
            return;
        }
    }
    print("这一页没有符合条件的报价");
}
buy_one_pearl();

